// TripQuest 的原創圖形：紙飛機、背包（Yolin 2026-10-27 核准；草圖 docs/sketches/原創圖形草圖.svg 的 A／B），
// 加上六隻吉祥物（2026-11-13；Yolin 看過第 5 版：「可以試著放進App」）。
// 原本這裡寫「就這兩個，不要加第三個」——那是吉祥物解禁之前的規定，2026-11-12 Yolin 解禁、11-13 同意放進 App，作廢。
// 吉祥物是「試著」放：整段在一個獨立的 commit，要拔就 revert 那一個 commit
// （背包的函式與樣式沒刪：拔掉時頁首換回 backpack() 就回到原樣）。
//
//   紙飛機（日期軸的標記，停在選中那一天上面、機頭朝右＝下一天）：兩個三角形＋一條折線。
//   背包（2026-11-13 以前的頁首識別；現在頁首放雪納瑞的頭，背包留著備用）：圓弧提把＋圓角矩形本體＋上蓋線＋前口袋。
//
// 紙飛機與背包為什麼跟任何授權角色都沒有關聯：只用三角形、圓角矩形、圓弧、直線這幾種幾何形，
// 沒有臉、不擬人；也沒有任何文字或商標。形狀是照草圖自己畫的座標，不是從任何圖庫或角色描下來的。
// 顏色不寫死：線條用 --text、色塊用 --primary／--accent／--ok（CSS 的 .gl-* 類別），深色與和紙各自套自己的值。
//
// 吉祥物（六隻平等；畫面上不寫名字；誰放哪裡見 MASCOT_SPOT）：雪納瑞、白兔、白熊、玄鳳鸚鵡、鷹、山雀。
// 原創性的檢查（把名字拿掉，會不會被認成某一隻特定角色；每隻跟同物種常見角色的明確不同處）見 docs/吉祥物原創性檢查.md。
// 圖是自己用通用的可愛畫法（大頭、短手腳、粗外框、腮紅）畫的座標，不是從任何角色、圖庫或參考圖描或量下來的。
// 正本就是下面 ART 的字串（產圖的程式在當時的工作暫存區、不在 repo；要改圖就改這裡）。
// 顏色寫在圖裡（吉祥物的毛色、衣服不跟主題變）；深色主題另外加白邊，見 mascot() 上面的說明。
//
// 全部純裝飾，一律 aria-hidden；意思由旁邊的字講（「第 N 天」、標題、「還沒有旅程」…）。
// 輸入全是本檔的常數字串（同 install.js 的圖示），不接任何外來資料。

const NS = 'http://www.w3.org/2000/svg';

function svg(viewBox, cls, inner, w, hgt) {
  const el = document.createElementNS(NS, 'svg');
  el.setAttribute('viewBox', viewBox);
  el.setAttribute('width', String(w));
  el.setAttribute('height', String(hgt));
  el.setAttribute('aria-hidden', 'true');
  el.setAttribute('focusable', 'false');
  el.setAttribute('class', cls);
  el.innerHTML = inner;
  return el;
}

export function paperPlane(w = 30) {
  return svg('-3 -3 62 52', 'gl gl-plane',
    '<polygon class="gl-paper" points="0,22 56,0 30,46"/>'
    + '<polygon class="gl-wing" points="30,46 26,30 56,0"/>'
    + '<line class="gl-fold" x1="26" y1="30" x2="0" y2="22"/>',
    w, Math.round(w * 52 / 62));
}

export function backpack(hgt = 26) {
  return svg('0 0 56 64', 'gl gl-pack',
    '<path class="gl-strap" d="M14 10 Q14 2 22 2 H34 Q42 2 42 10"/>'
    + '<rect class="gl-body" x="4" y="10" width="48" height="50" rx="14"/>'
    + '<path class="gl-flap" d="M4 26 Q28 36 52 26"/>'
    + '<rect class="gl-pocket" x="16" y="38" width="24" height="15" rx="5"/>',
    Math.round(hgt * 56 / 64), hgt);
}

// ---- 吉祥物 ----
// 每個出場處固定一隻（Yolin：六隻平等、次數差不多；雪納瑞放最重要的頁首）。這張表就是「誰在哪裡」的決定，改這裡就好。
export const MASCOT_SPOT = Object.freeze({
  header: 'schnauzer',   // 頁首標題左邊（只放頭，跟原本的背包一樣高 → 頁首高度不變）
  empty: 'bunny',        // 空白頁：「我的旅程」還沒有旅程（揮手打招呼）
  loading: 'hawk',       // 載入中：spinnerBox（讀邀請、整理回顧、查天氣；拿望遠鏡在找）
  done: 'cockatiel',     // 完成任務：加照片完成任務的慶祝畫面（打領結、頭冠翹起來）
  recap: 'bear',         // 行程回顧：最終回顧的標題上面
  settings: 'tit',       // 設定頁：「關於」那張卡
});

const MASCOT_VB = '-6 -6 212 252';   // 畫布 200×240，四邊各留 6：深色的白邊（外擴 5）才不會被裁掉
const HEAD_VB = '36 38 128 116';     // 頁首只裁雪納瑞的頭
let rimSeq = 0;

// 深色主題的白邊：沿剪影外擴 5、塗白、墊在原圖下面（深底上黑外框才分得出輪廓）。
// 濾鏡寫成 SVG 的 filter 屬性、每一張的 id 都不同（同一頁有好幾張也不會互相指錯）；
// 和紙主題由 CSS 關掉（html[data-theme="washi"] .mc-fig { filter: none }——CSS 蓋得過 SVG 的屬性）。
// 地面陰影與動作線只在和紙畫：深底上幾乎看不到，白邊版本來就不畫（CSS 的 .mc-shadow／.mc-extra）。
function rimDefs(id) {
  return `<defs><filter id="${id}" x="-15%" y="-15%" width="130%" height="130%">`
    + '<feMorphology in="SourceAlpha" operator="dilate" radius="5" result="d"/><feFlood flood-color="#ffffff"/>'
    + '<feComposite in2="d" operator="in" result="w"/>'
    + '<feMerge><feMergeNode in="w"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>';
}

function figure(kind, viewBox, withGround, w, hgt, cls) {
  const a = ART[kind];
  if (!a) throw new Error('沒有這隻吉祥物：' + kind);
  const seq = ++rimSeq;
  const id = `tq-rim-${seq}`;
  // 圖裡的 id（裁切框）是 i0、i1…，每一張加上自己的流水號：同一頁放好幾張時，引用才不會指到別張的裁切框
  const pose = a.pose.replace(/(\bid="|url\(#)(i\d+)(?=[")])/g, `$1mc${seq}-$2`);
  const el = svg(viewBox, cls,
    rimDefs(id)
    + (withGround ? `<g class="mc-shadow">${a.shadow}</g>` : '')
    + `<g class="mc-fig" filter="url(#${id})">${pose}</g>`
    + (withGround && a.extra ? `<g class="mc-extra">${a.extra}</g>` : ''),
    w, hgt);
  el.setAttribute('data-mascot', kind);
  return el;
}

// 整隻（含地面陰影與動作線）。hgt 是畫面上的高度（px）。
// 注意：不要掛 .gl 類別——.gl 的樣式會把每一條線改成字色，吉祥物的顏色寫在圖裡。
export function mascot(kind, hgt = 96) {
  return figure(kind, MASCOT_VB, true, Math.round(hgt * 212 / 252), hgt, `gl-mascot mc-${kind}`);
}

// 頁首的頭（雪納瑞）：高度預設 26，跟原本的背包一樣
export function mascotHead(hgt = 26) {
  return figure(MASCOT_SPOT.header, HEAD_VB, false, Math.round(hgt * 128 / 116), hgt, 'gl-mascot gl-mascot-head');
}

// ---- 拍照圖示（2026-11-13 第四段；Yolin：「甚至拍照那些圖示也可以一起換掉」）----
// 「拍照」「從相簿選」兩顆按鈕：**功能的形狀當主體**（相機、一張相片），吉祥物只從邊上探出來——
// 相機後面是雪納瑞的頭頂、折耳、眉毛，兩隻手扶著機身；相片後面冒出白兔的兩隻耳朵。
// 按鈕大小不變（任務列 46×46、展開後的大按鈕照舊），圖示是裝飾、aria-hidden：意思由按鈕自己的 aria-label／字講。
// 圖裡沒有 id：每一列任務都有一組，同一頁幾十個也不會互相指錯。畫布 64×64。
export function photoIcon(kind, size = 30) {
  const a = ICON[kind];
  if (!a) throw new Error('沒有這個圖示：' + kind);
  const el = svg('0 0 64 64', `gl-icon gl-icon-${kind}`, a, size, size);
  el.setAttribute('data-icon', kind);
  return el;
}

